_error('descripcion') ?></div><div class="sm:col-span-2"><label class="label">Ubicación o área</label><input name="ubicacion" class="input" value="<?= e(old('ubicacion', $employee['area'] ?? '')) ?>" placeholder="Ej. Oficina 402, área de producto"></div><div class="sm:col-span-2 flex items-center justify-between gap-4"><p class="max-w-sm text-[10px] leading-5 text-slate-400">Tu reporte será visible para el equipo autorizado de SG-SST. Se gestionará con reserva y sin represalias.</p><button class="btn-primary shrink-0" type="submit">Enviar reporte o consulta <?= icon('arrow-right', 'h-4 w-4') ?></button></div></form></div></section>
